from __future__ import annotations


def build_trading_records_ui() -> str:
    return """<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><title>交易记录 V3.23</title>
<style>body{margin:0;background:#0b1020;color:#dbeafe;font-family:Segoe UI,Microsoft YaHei,Arial,sans-serif}header{height:58px;display:flex;align-items:center;gap:12px;padding:0 18px;background:#101827;border-bottom:1px solid #283956}.brand{font-weight:900;font-size:20px;color:#bfdbfe}.grow{flex:1}a{color:#bfdbfe}.wrap{padding:14px}.bar{display:flex;gap:10px;align-items:center;margin-bottom:12px}select,input,button{background:#1f2937;color:#e5e7eb;border:1px solid #374151;border-radius:9px;padding:8px}button{background:#2563eb;border:0;font-weight:800}.panel{background:#111827;border:1px solid #26364f;border-radius:14px;overflow:hidden}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border-bottom:1px solid #26364f;padding:8px;vertical-align:top;overflow-wrap:anywhere}th{background:#141f35;color:#93c5fd}.muted{color:#91a7c7}</style></head><body><header><div class="brand">统一交易记录 V3.23</div><div class="grow"></div><a href="/live-trading">真实交易</a><a href="/realtime-paper">实时模拟</a><a href="/backtest">回测</a></header><div class="wrap"><div class="bar"><select id="mode"><option value="">全部模式</option><option value="backtest">回测</option><option value="realtime_paper">实时模拟</option><option value="live">真实交易</option></select><input id="symbol" placeholder="代码"><button onclick="load()">查询</button><span class="muted">研究辅助，不构成投资建议；真实交易需用户自行确认合规与风险。</span></div><div class="panel"><table><thead><tr><th>时间</th><th>表</th><th>模式</th><th>代码</th><th>状态/事件</th><th>详情</th></tr></thead><tbody id="rows"><tr><td colspan="6">Loading...</td></tr></tbody></table></div></div><script>
const $=id=>document.getElementById(id);function esc(s){return String(s??'').replace(/[&<>]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[m]))}async function load(){const p=new URLSearchParams({mode:$('mode').value,symbol:$('symbol').value,limit:'200'});const js=await fetch('/api/trading-records?'+p).then(r=>r.json());const rows=js.data||[];$('rows').innerHTML=rows.map(x=>`<tr><td>${esc(x.created_at||x.timestamp||'')}</td><td>${esc(x.table||'')}</td><td>${esc(x.mode||'')}</td><td>${esc(x.symbol||'')}</td><td>${esc(x.status||x.event_type||x.action||'')}</td><td>${esc(JSON.stringify(x)).slice(0,700)}</td></tr>`).join('')||'<tr><td colspan="6">暂无记录</td></tr>'}load()
</script></body></html>"""
